class Solution {
public:
    string reformatDate(string date) {
        int i = 0;
        while (date[i] >= '0' && date[i] <= '9') i++;
        char m1 = date[i + 3];
        char m2 = date[i + 4];
        char m3 = date[i + 5];
        int monthNum;
        switch (m1) {
            case 'J': monthNum = (m2 == 'a') ? 1 : ((m3 == 'n') ? 6 : 7); break;
            case 'F': monthNum = 2; break;
            case 'M': monthNum = (m3 == 'r') ? 3 : 5; break;
            case 'A': monthNum = (m2 == 'p') ? 4 : 8; break;
            case 'S': monthNum = 9; break;
            case 'O': monthNum = 10; break;
            case 'N': monthNum = 11; break;
            case 'D': monthNum = 12; break;
            default: monthNum = 0; break;
        }
        string result(10, '0');
        result[0] = date[i + 7];
        result[1] = date[i + 8];
        result[2] = date[i + 9];
        result[3] = date[i + 10];
        result[4] = '-';
        result[5] = static_cast<char>('0' + monthNum / 10);
        result[6] = static_cast<char>('0' + monthNum % 10);
        result[7] = '-';
        if (i == 1) {
            result[8] = '0';
            result[9] = date[0];
        } else {
            result[8] = date[0];
            result[9] = date[1];
        }
        return result;
    }
};
